-- Evidence-backed gaps from NEW HeaALTHCAROLOGY AFRICA PALTFORM.docx.
alter table public.patients add column if not exists patient_type text not null default 'Standard Patient',add column if not exists ethnicity text,add column if not exists ethnicity_other text,add column if not exists gender_identity text,add column if not exists gender_other text,add column if not exists preferred_language text,add column if not exists birth_country_id bigint references public.countries(id),add column if not exists service_identifier text,add column if not exists service_rank text,add column if not exists service_unit text,add column if not exists dependent_relationship text,add column if not exists related_service_member_name text,add column if not exists related_service_identifier text;
alter table public.patients add constraint patients_type_check check(patient_type in ('Military Dependent','Military','Police Dependent','Police','Standard Patient','Public Servant / Fonctionnaire','Public Servant / Fonctionnaire Dependent','Personnel CIVIL (PERCI) / Civilian Personnel','Personnel CIVIL (PERCI) / Civilian Personnel Dependent'));
alter table public.patients add constraint patients_ethnicity_other_check check(ethnicity<>'Other' or nullif(btrim(ethnicity_other),'') is not null);
alter table public.patients add constraint patients_gender_other_check check(gender_identity<>'Other' or nullif(btrim(gender_other),'') is not null);

create table public.patient_contact_methods(id bigint generated by default as identity primary key,patient_id bigint not null references public.patients(id) on delete cascade,contact_type text not null check(contact_type in ('phone','email')),country_calling_code text,contact_value text not null,label text,primary_contact boolean not null default false,verified_at timestamptz,created_at timestamptz not null default now());
create unique index one_primary_contact_per_type on public.patient_contact_methods(patient_id,contact_type) where primary_contact;
create table public.facility_patient_categories(id uuid primary key default gen_random_uuid(),facility_id uuid not null references public.facilities(id) on delete cascade,category_code text not null,name text not null,description text,active boolean not null default true,unique(facility_id,category_code));
create table public.patient_category_assignments(patient_id bigint not null references public.patients(id) on delete cascade,facility_category_id uuid not null references public.facility_patient_categories(id) on delete cascade,assigned_at timestamptz not null default now(),primary key(patient_id,facility_category_id));

create table public.insurance_organizations(id uuid primary key default gen_random_uuid(),facility_id uuid references public.facilities(id) on delete cascade,name text not null,address text,phone text,email text,website text,contact_person text,active boolean not null default true);
create table public.insurance_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.insurance_organizations(id) on delete cascade,category_code text,name text not null,copay_amount numeric(12,2),coverage_percent numeric(5,2),currency char(3),active boolean not null default true,check(coverage_percent between 0 and 100));
create table public.patient_insurance_enrollments(id uuid primary key default gen_random_uuid(),patient_id bigint not null references public.patients(id) on delete cascade,plan_id uuid not null references public.insurance_plans(id),healthcare_identification_number text not null,enrollment_date date,expiration_date date,primary_plan boolean not null default false,unique(plan_id,healthcare_identification_number));

create table public.vital_sign_observations(id bigint generated by default as identity primary key,facility_id uuid not null references public.facilities(id),patient_id bigint not null references public.patients(id) on delete cascade,encounter_id bigint references public.encounters(id) on delete cascade,recorded_by uuid references auth.users(id),recorded_at timestamptz not null default now(),weight_kg numeric(7,2),height_cm numeric(7,2),temperature_c numeric(5,2),oxygen_saturation numeric(5,2),respiratory_rate integer,heart_rate integer,systolic_bp integer,diastolic_bp integer,check(oxygen_saturation between 0 and 100));
create table public.care_queue_entries(id uuid primary key default gen_random_uuid(),facility_id uuid not null references public.facilities(id),patient_id bigint not null references public.patients(id),encounter_id bigint references public.encounters(id),queue_stage text not null default 'reception' check(queue_stage in ('reception','triage','consultation','completed','cancelled')),arrival_number integer not null,reference_number text not null,department_id bigint references public.departments(id),service_id bigint references public.services(id),assigned_provider_id bigint references public.providers(id),priority text not null default 'normal' check(priority in ('normal','medium','high')),billing_generated boolean not null default false,started_at timestamptz not null default now(),ended_at timestamptz,created_by uuid not null references auth.users(id),unique(facility_id,reference_number));
create table public.encounter_contributors(encounter_id bigint not null references public.encounters(id) on delete cascade,provider_id bigint not null references public.providers(id),can_read boolean not null default true,can_write boolean not null default true,assigned_by uuid not null references auth.users(id),assigned_at timestamptz not null default now(),primary key(encounter_id,provider_id));

create table public.ambulance_vehicles(id uuid primary key default gen_random_uuid(),facility_id uuid not null references public.facilities(id),vehicle_name text not null,vehicle_type text,registration_number text,active boolean not null default true,unique(facility_id,vehicle_name));
create table public.ambulance_transports(id uuid primary key default gen_random_uuid(),facility_id uuid not null references public.facilities(id),ambulance_id uuid references public.ambulance_vehicles(id),patient_id bigint not null references public.patients(id),departing_at timestamptz,arrival_at timestamptz,starting_location text,destination_facility_id uuid references public.facilities(id),starting_latitude numeric(9,6),starting_longitude numeric(9,6),starting_kilometer numeric(12,2),arrival_kilometer numeric(12,2),reason text,driver_user_id uuid references auth.users(id),emergency_level text check(emergency_level in ('Planned','Medium','Serious','Vital')),starting_vitals jsonb not null default '{}'::jsonb,arrival_vitals jsonb not null default '{}'::jsonb,patient_condition text,interventions text,equipment_used text,observations text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.ambulance_transport_team(transport_id uuid not null references public.ambulance_transports(id) on delete cascade,user_id uuid not null references auth.users(id),function text,primary key(transport_id,user_id));

create table public.prenatal_episodes(id uuid primary key default gen_random_uuid(),facility_id uuid not null references public.facilities(id),patient_id bigint not null references public.patients(id),estimated_due_date date,partograph_status text,partograph_closed_at timestamptz,childbirth_outcome_code text,childbirth_outcome_display text,opened_at timestamptz not null default now(),closed_at timestamptz,created_by uuid not null references auth.users(id));
create table public.prenatal_visits(id uuid primary key default gen_random_uuid(),episode_id uuid not null references public.prenatal_episodes(id) on delete cascade,encounter_id bigint references public.encounters(id),provider_id bigint references public.providers(id),visited_at timestamptz not null default now(),weight_g numeric(9,2),height_cm numeric(7,2),cranial_perimeter_cm numeric(7,2),notes text);
create table public.data_export_audit(id bigint generated by default as identity primary key,facility_id uuid references public.facilities(id),exported_by uuid not null references auth.users(id),export_type text not null check(export_type in ('CSV','PDF')),module text not null,filter_parameters jsonb not null default '{}'::jsonb,exported_at timestamptz not null default now());

do $$ declare t text; begin foreach t in array array['patient_contact_methods','facility_patient_categories','patient_category_assignments','insurance_organizations','insurance_plans','patient_insurance_enrollments','vital_sign_observations','care_queue_entries','encounter_contributors','ambulance_vehicles','ambulance_transports','ambulance_transport_team','prenatal_episodes','prenatal_visits','data_export_audit'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create policy contacts_access on public.patient_contact_methods for all to authenticated using(private.is_aal2() and exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id))) with check(private.is_aal2() and exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id)));
create policy categories_access on public.facility_patient_categories for all to authenticated using(private.is_aal2() and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_facility_member(facility_id));
create policy category_assignments_access on public.patient_category_assignments for all to authenticated using(private.is_aal2() and exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id))) with check(private.is_aal2() and exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id)));
create policy insurers_access on public.insurance_organizations for all to authenticated using(private.is_aal2() and (facility_id is null or private.is_facility_member(facility_id))) with check(private.is_aal2() and facility_id is not null and private.is_facility_member(facility_id));
create policy plans_access on public.insurance_plans for all to authenticated using(private.is_aal2() and exists(select 1 from public.insurance_organizations o where o.id=organization_id and (o.facility_id is null or private.is_facility_member(o.facility_id)))) with check(private.is_aal2() and exists(select 1 from public.insurance_organizations o where o.id=organization_id and o.facility_id is not null and private.is_facility_member(o.facility_id)));
create policy enrollments_access on public.patient_insurance_enrollments for all to authenticated using(private.is_aal2() and exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id))) with check(private.is_aal2() and exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id)));
create policy vitals_access on public.vital_sign_observations for all to authenticated using(private.is_aal2() and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_facility_member(facility_id));
create policy queues_access on public.care_queue_entries for all to authenticated using(private.is_aal2() and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_facility_member(facility_id));
create policy contributors_access on public.encounter_contributors for all to authenticated using(private.is_aal2() and exists(select 1 from public.encounters e join public.patients p on p.id=e.patient_id where e.id=encounter_id and p.facility_id is not null and private.is_facility_member(p.facility_id))) with check(private.is_aal2() and exists(select 1 from public.encounters e join public.patients p on p.id=e.patient_id where e.id=encounter_id and p.facility_id is not null and private.is_facility_member(p.facility_id)));
create policy ambulances_access on public.ambulance_vehicles for all to authenticated using(private.is_aal2() and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_facility_member(facility_id));
create policy transports_access on public.ambulance_transports for all to authenticated using(private.is_aal2() and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_facility_member(facility_id));
create policy transport_team_access on public.ambulance_transport_team for all to authenticated using(private.is_aal2() and exists(select 1 from public.ambulance_transports a where a.id=transport_id and private.is_facility_member(a.facility_id))) with check(private.is_aal2() and exists(select 1 from public.ambulance_transports a where a.id=transport_id and private.is_facility_member(a.facility_id)));
create policy prenatal_access on public.prenatal_episodes for all to authenticated using(private.is_aal2() and private.is_facility_member(facility_id)) with check(private.is_aal2() and private.is_facility_member(facility_id));
create policy prenatal_visits_access on public.prenatal_visits for all to authenticated using(private.is_aal2() and exists(select 1 from public.prenatal_episodes e where e.id=episode_id and private.is_facility_member(e.facility_id))) with check(private.is_aal2() and exists(select 1 from public.prenatal_episodes e where e.id=episode_id and private.is_facility_member(e.facility_id)));
create policy export_audit_access on public.data_export_audit for select to authenticated using(private.is_aal2() and (private.is_platform_root() or (facility_id is not null and private.is_facility_member(facility_id))));
create policy export_audit_append on public.data_export_audit for insert to authenticated with check(private.is_aal2() and exported_by=(select auth.uid()) and (facility_id is null or private.is_facility_member(facility_id)));
do $$ declare t text; begin foreach t in array array['patient_contact_methods','facility_patient_categories','patient_category_assignments','insurance_organizations','insurance_plans','patient_insurance_enrollments','vital_sign_observations','care_queue_entries','encounter_contributors','ambulance_vehicles','ambulance_transports','ambulance_transport_team','prenatal_episodes','prenatal_visits','data_export_audit'] loop execute format('grant select,insert,update,delete on public.%I to authenticated',t);end loop;end $$;
create index care_queue_facility_stage_idx on public.care_queue_entries(facility_id,queue_stage,priority,started_at);create index vitals_patient_time_idx on public.vital_sign_observations(patient_id,recorded_at desc);create index ambulance_transports_facility_time_idx on public.ambulance_transports(facility_id,departing_at);create index prenatal_patient_idx on public.prenatal_episodes(patient_id,opened_at desc);
